<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_permission('MOVIMIENTO_VER');$year=max(2020,min(2100,(int)($_GET['year']??date('Y'))));$month=max(0,min(12,(int)($_GET['month']??0)));$dep=(int)($_GET['departamento_id']??0);$type=strtoupper(trim((string)($_GET['tipo']??'')));$status=strtoupper(trim((string)($_GET['estatus']??'')));$q=trim((string)($_GET['q']??''));$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$ids=visible_department_ids($db,$user);if($dep>0){if(!user_is_global($user)&&!in_array($dep,$ids,true)){$db->close();json_response(['ok'=>true,'data'=>[]]);}$ids=[$dep];}if(!$ids){$db->close();json_response(['ok'=>true,'data'=>[]]);}$where=["pm.ejercicio=$year",'pm.departamento_id IN ('.implode(',',array_map('intval',$ids)).')'];if($month>=1&&$month<=12)$where[]="MONTH(pm.fecha)=$month";if(in_array($type,['ENTRADA','SALIDA'],true))$where[]="pm.tipo='".$db->real_escape_string($type)."'";if(in_array($status,['REGISTRADO','CANCELADO'],true))$where[]="pm.estatus='".$db->real_escape_string($status)."'";if($q!==''){$esc=$db->real_escape_string($q);$where[]="(pm.folio LIKE '%$esc%' OR pm.concepto LIKE '%$esc%' OR pm.beneficiario_nombre LIKE '%$esc%' OR pm.referencia LIKE '%$esc%' OR d.nombre LIKE '%$esc%' OR s.nombre LIKE '%$esc%')";}$sql="SELECT pm.*,d.nombre departamento,d.codigo departamento_codigo,s.nombre subitem,CONCAT_WS(' ',us.nombre,us.apellido_paterno,us.apellido_materno) solicitado_por,CONCAT_WS(' ',uo.nombre,uo.apellido_paterno,uo.apellido_materno) otorgado_a,CONCAT_WS(' ',ur.nombre,ur.apellido_paterno,ur.apellido_materno) registrado_por,(SELECT COUNT(*) FROM movimiento_aclaracion a WHERE a.movimiento_id=pm.movimiento_id AND a.estatus IN ('ABIERTA','EN_REVISION')) aclaraciones_abiertas FROM presupuesto_movimiento pm JOIN departamento d ON d.departamento_id=pm.departamento_id LEFT JOIN presupuesto_subitem s ON s.subitem_id=pm.subitem_id LEFT JOIN usuario us ON us.usuario_id=pm.solicitado_por_usuario_id LEFT JOIN usuario uo ON uo.usuario_id=pm.otorgado_a_usuario_id JOIN usuario ur ON ur.usuario_id=pm.registrado_por_usuario_id WHERE ".implode(' AND ',$where)." ORDER BY pm.fecha DESC,pm.movimiento_id DESC LIMIT 500";$rs=$db->query($sql);$data=[];while($r=$rs->fetch_assoc()){if(!movement_is_visible($db,$user,$r))continue;$r['movimiento_id']=(int)$r['movimiento_id'];$r['departamento_id']=(int)$r['departamento_id'];$r['monto']=(float)$r['monto'];$r['aclaraciones_abiertas']=(int)$r['aclaraciones_abiertas'];$data[]=$r;}$db->close();json_response(['ok'=>true,'data'=>$data]);
